"""WebRTC page HTML builders (stream / dashboard / slots)."""
from __future__ import annotations

# Base64-encoded page HTML. Decode at call time — avoids all escaping issues.
import base64 as _b64

_INDEX_B64     = ''

_DASHBOARD_B64 = ''

_SLOTS_CSS_B64  = ''


def build_webrtc_index_html() -> str:
    """Return the live stream viewer page HTML."""
    return _b64.b64decode(_INDEX_B64).decode()


def build_dashboard_html() -> str:
    """Return the monitoring dashboard page HTML."""
    return _b64.b64decode(_DASHBOARD_B64).decode()


def build_slots_html(slot_api_port: int = 8090) -> str:
    """Return the slot management page HTML."""
    api = f"http://localhost:{slot_api_port}"
    css = _b64.b64decode(_SLOTS_CSS_B64).decode()
    _slots_body_b64 = ''
    body = _b64.b64decode(_slots_body_b64).decode().replace("__SLOT_API_URL__", api)
    return (
        "<!doctype html>\n<html lang=\"en\">\n<head>\n"
        "<meta charset=\"utf-8\">\n"
        "<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n"
        "<title>Sessions \u2014 Deonar AI</title>\n"
        '<script src="https://cdn.jsdelivr.net/npm/alpinejs@3.14.1/dist/cdn.min.js" defer></script>\n'
        "<style>\n" + css + "\n</style>\n"
        "</head>\n<body>\n" + body + "\n</body>\n</html>"
    )
